SELECT d.document_id, d.revision, r.source_id, r.target_id, r.direction, r.mode, r.status, o1.missing AS source_missing, o2.missing AS target_missing, s.missing AS sketch_missing FROM main.cad_relation AS r JOIN main.cad_object AS o1 ON r.source_id = o1.object_id JOIN main.cad_object AS o2 ON r.target_id = o2.object_id LEFT JOIN main.cad_document AS d ON o1.object_id = d.selected_object_id LEFT JOIN main.cad_sketch_owner AS s ON r.source_id = s.object_id WHERE r.target_id = 'solid'
